<?php
function nisRenderTracker(array $data,string $type,string $error=''): void {
    $patients=$type==='patients';$filter=$data['filter'];$route=$patients?'patient_live_tracker.php':'bed_tracker.php';
    ?>
    <div class="nis-workspace"><header class="nis-heading"><div><p class="nis-eyebrow">NURSYNC / MONITORING</p><h2><?php echo $patients?'Patient Tracker':'Bed Tracker'; ?></h2><p><?php echo $patients?'Authorized patient locations and encounter movements.':'Department availability from existing bed and critical-unit ledgers.'; ?></p></div><a href="<?php echo h($route.'?'.http_build_query($filter)); ?>" class="nis-button" data-tracker-refresh>Refresh</a></header>
    <?php if($error): ?><div role="alert" class="alert alert-danger"><?php echo h($error); ?></div><?php endif; ?>
    <?php if(!$patients): ?><section class="nis-metrics" aria-label="Bed availability">
    <?php foreach(['total'=>'Total beds','available'=>'Available','occupied'=>'Occupied','reserved'=>'Reserved','out_of_service'=>'Out of service','unverified'=>'Requires verification'] as $key=>$label): ?><div class="nis-metric"><span><?php echo h($label); ?></span><strong><?php echo ($error||($key==='reserved'&&!$data['reservation_supported'])||($key==='out_of_service'&&!($data['out_of_service_supported']??false)))?'—':(int)($data['summary'][$key]??0); ?></strong><?php if($key==='reserved'&&!$data['reservation_supported']): ?><small>Reservation state not recorded</small><?php endif; ?><?php if($key==='out_of_service'&&!($data['out_of_service_supported']??false)): ?><small>Service state not recorded</small><?php endif; ?><?php if(in_array($key,['reserved','out_of_service'],true)&&($data['partial_state_coverage']??false)): ?><small>Configured unit slots have no state ledger</small><?php endif; ?></div><?php endforeach; ?></section><?php endif; ?>
    <?php foreach($data['notices']??[] as $notice): ?><p class="nis-notice"><?php echo h($notice); ?></p><?php endforeach; ?>
    <section class="nis-panel"><form method="get" class="nis-filters" data-tracker-filters role="search">
    <?php if($patients): ?><label>Patient or Hospital Number<input type="search" name="q" value="<?php echo h($filter['q']); ?>" placeholder="Name, Hospital Number, encounter"></label><?php endif; ?>
    <label>Department<select name="department"><option value="">All permitted locations</option><?php foreach(nisTrackerUnits() as $unit): ?><option value="<?php echo h($unit); ?>" <?php echo $filter['department']===$unit?'selected':''; ?>><?php echo h(nisDepartmentLabel($unit)); ?></option><?php endforeach; ?></select></label>
    <label><?php echo $patients?'Encounter / clinical status':'Bed status'; ?><select name="status"><option value="">All statuses</option><?php foreach($patients?patientStatusWorkflow():['available'=>'Available','occupied'=>'Occupied','reserved'=>'Reserved','out_of_service'=>'Out of service','unverified'=>'Requires verification'] as $key=>$label): ?><option value="<?php echo h($key); ?>" <?php echo $filter['status']===$key?'selected':''; ?>><?php echo h($label); ?></option><?php endforeach; ?></select></label>
    <?php if($patients): ?><label>Transfer status<select name="transfer_status"><option value="">All movements</option><?php foreach(['PENDING','ACCEPTED','IN TRANSIT','RECEIVED','REJECTED','CANCELLED','ARRIVED','COMPLETED'] as $status): ?><option <?php echo $filter['transfer_status']===$status?'selected':''; ?>><?php echo h($status); ?></option><?php endforeach; ?></select></label><?php endif; ?>
    <button class="nis-button nis-primary">Apply filters</button><a class="nis-button" href="<?php echo $route; ?>">Clear</a></form>
    <p class="nis-help" role="status" aria-live="polite" data-tracker-status><?php echo (int)$data['total']; ?> matching records · Updated <?php echo h(date('M d, Y H:i:s')); ?></p>
    <div class="nis-table-wrap"><table class="nis-table"><thead><tr>
    <?php foreach($patients?['Patient / encounter','Current department','Bed / location','Encounter status','Admission status','Transfer status','Actions']:['Department','Bed / slot','Current status','Ledger status','Assignment'] as $label): ?><th scope="col"><?php echo h($label); ?></th><?php endforeach; ?></tr></thead><tbody>
    <?php foreach($data['rows'] as $row): ?>
    <?php if($patients): ?><tr><td data-label="Patient / encounter"><strong><?php echo h($row['patient_name']); ?></strong><span>HN <?php echo h($row['permanent_patient_id']?:'Not recorded'); ?></span><small>Encounter <?php echo h($row['patient_code']); ?></small></td><td data-label="Current department"><?php echo h($row['department']?nisDepartmentLabel($row['department']):'Not recorded'); ?></td><td data-label="Bed / location"><?php echo h($row['bed_number']?:'No bed recorded'); ?></td><td data-label="Encounter status"><?php echo h(statusLabel($row['status'])); ?></td><td data-label="Admission status"><?php echo h($row['admission_status']); ?></td><td data-label="Transfer status"><?php echo h($row['transfer_status']?:'No movement'); ?></td><td data-label="Actions"><a class="nis-button" href="patient_live_tracker.php?patient_id=<?php echo (int)$row['patient_id']; ?>">Movement history</a><?php if($row['can_open_chart']): ?> <a class="nis-button" href="patient_detail.php?id=<?php echo (int)$row['patient_id']; ?>">Patient record</a><?php else: ?><small>Tracking access only</small><?php endif; ?></td></tr>
    <?php else: ?><tr><td data-label="Department"><?php echo h(nisDepartmentLabel($row['department'])); ?></td><td data-label="Bed / slot"><?php echo h($row['bed_number']); ?></td><td data-label="Current status"><?php echo h(ucwords(str_replace('_',' ',$row['status']))); ?></td><td data-label="Ledger status"><?php echo h($row['recorded_status']); ?><?php if($row['conflict']): ?> <strong>Verify conflicting assignment</strong><?php endif; ?></td><td data-label="Assignment"><?php echo $row['has_assignment']?'Assigned (patient details restricted)':'No active assignment'; ?></td></tr><?php endif; ?>
    <?php endforeach; ?>
    <?php if(!$data['rows']): ?><tr><td colspan="<?php echo $patients?7:5; ?>"><div class="nis-empty"><strong><?php echo $error?'Tracker unavailable':'No matching records'; ?></strong><p><?php echo $error?'Retry using Refresh.':'Adjust the filters or refresh. Only authorized records and registered beds are shown.'; ?></p></div></td></tr><?php endif; ?>
    </tbody></table></div>
    <nav class="nis-pagination" aria-label="Tracker pages"><span>Page <?php echo (int)$filter['page']; ?> of <?php echo (int)$data['pages']; ?></span><?php foreach([-1=>'Previous',1=>'Next'] as $offset=>$label): $page=$filter['page']+$offset;if($page<1||$page>$data['pages'])continue; ?><a class="nis-button" href="<?php echo h($route.'?'.http_build_query(array_merge($filter,['page'=>$page]))); ?>"><?php echo $label; ?></a><?php endforeach; ?></nav></section>
    <?php if($patients&&$filter['patient_id']): ?><section class="nis-panel"><div class="nis-panel-title"><h3>Authorized movement history</h3></div><p class="nis-help">Most recent 100 authorized movements for this encounter.</p><div class="nis-table-wrap"><table class="nis-table"><thead><tr><th>Encounter</th><th>Sending unit</th><th>Receiving unit</th><th>Status</th><th>Recorded time</th></tr></thead><tbody><?php foreach($data['history'] as $movement): ?><tr><td data-label="Encounter"><?php echo h($movement['encounter_id']); ?></td><td data-label="Sending unit"><?php echo h(nisDepartmentLabel($movement['source_department'])); ?></td><td data-label="Receiving unit"><?php echo h(nisDepartmentLabel($movement['destination_department'])); ?></td><td data-label="Status"><?php echo h($movement['status']); ?></td><td data-label="Recorded time"><?php echo h($movement['movement_date_time']?:$movement['created_at']); ?></td></tr><?php endforeach; ?><?php if(!$data['history']): ?><tr><td colspan="5">No authorized movement history found for this encounter.</td></tr><?php endif; ?></tbody></table></div></section><?php endif; ?></div>
    <?php
}
